#' Propensity Score and Overlap
#'
#' 
#' @param data .
#' @param treat .
#' @param covs .
#' @param weights .
#' @param link .
#' @param trim .
#' @param trimLo .
#' @param trimHi .
#' @param level .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$coef} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$overlap} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$psPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$coef$asDF}
#'
#' \code{as.data.frame(results$coef)}
#'
#' @export
psmodel <- function(
    data,
    treat,
    covs,
    weights,
    link = "logit",
    trim = "none",
    trimLo = 0.05,
    trimHi = 0.95,
    level = 95,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("psmodel requires jmvcore to be installed (restart may be required)")

    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(weights)) weights <- jmvcore::resolveQuo(jmvcore::enquo(weights))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(weights), weights, NULL))


    options <- psmodelOptions$new(
        treat = treat,
        covs = covs,
        weights = weights,
        link = link,
        trim = trim,
        trimLo = trimLo,
        trimHi = trimHi,
        level = level,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- psmodelClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

